    Д = НовыйНаборРегистров(20,0); Док = ТабличныйСнимокОпыта(Д);
    Возврат Новый Структура("Итог,НольЧислом,НольПодписан,ПустоОтдельно,ИсточникСохранён",Док.Область("R4C2").Значение,Док.Область("R3C2").Значение = 0,Док.Область("R3C2").Текст = "0",Док.Область("R5C2").Текст = "",Д.Первая.ДлительностьМинут = 20 И Д.Вторая.ДлительностьМинут = 0);
КонецФункции

