Процедура ПриНачалеРаботыСистемы()
    Р = УчебныеОтчёты.ОпытНуляВСнимке();
    Сообщить("Итого, минуты: " + Строка(Р.Итог));
    Сообщить("Ноль — число: " + Строка(Р.НольЧислом));
    Сообщить("Ноль виден как 0: " + Строка(Р.НольПодписан));
    Сообщить("Пустая ячейка отдельно: " + Строка(Р.ПустоОтдельно));
    Сообщить("Источник сохранён: " + Строка(Р.ИсточникСохранён));
